rating_encoder &lt;- function (x) {
  y &lt;- factor(
    if_else(
      is.na(x) | x == "NR",
      "NA",
      if_else(
        stringr::str_starts(x, "A"),
        "A",
        if_else(stringr::str_starts(x, "B"), "B", "C")
      )
    ),
    levels = c("NA", "A", "B", "C")
  )
}

